{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "On testing, a parent of a participating student would have to make sure the student takes each year the TCAP tests (or successor tests approved by the state board of education) given to public school students in the same grade or course subject.",
      "rationale": "Conveys the parent's duty, annual testing, authorized successor tests, and matching grade or course subject. The paragraph also states the alternate-assessment exemption."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "A student in grade 11 would have to take the exam given to public school grade 11 students under § 49-6-6001(b)(1).",
      "rationale": "Identifies the required examination and grade, but does not convey that the parent must ensure its administration; the express parental duty is limited to TCAP testing."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "A student in kindergarten through grade 3 would have to take each of the three Tennessee universal reading screeners, or screeners approved by the state board, in each of the three administration windows set by the department of education.",
      "rationale": "Covers the grades, screeners, alternatives, and administration windows, but omits the annual frequency and the parent's responsibility to ensure administration."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Test results would have to be reported to the parent.",
      "rationale": "Conveys mandatory parental reporting of the test results described in the paragraph."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Students with disabilities who would have taken the alternate assessment under their IEP would be exempt.",
      "rationale": "Conveys the disability-related exemption and its dependence on the student's IEP alternate-assessment determination."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "On transparency, a participating school would have to post on its website its lesson plans and syllabus for every class, a current list of the materials in its library collection, and the academic standards for each class.",
      "rationale": "Covers all required website postings and their class-by-class scope. The introduction identifies both sets of amended school provisions."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The bill defines \"library collection\" as materials made available to students, including as part of a course. It defines \"materials\" broadly, covering books, periodicals, films, video games, applications, and subscription content in any form.",
      "rationale": "Conveys the library-collection definition and some material categories, but omits expressly included categories such as newspapers, manuscripts, prints, documents, microfilm, discs, cassettes, and videotapes."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "On staffing, a participating school would have to make sure all its educators hold a valid license to teach in a public school issued by the state board of education.",
      "rationale": "Conveys the school's responsibility, coverage of all educators, license validity, public-school qualification, and issuing authority."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "On transparency, a participating school would have to post on its website its lesson plans and syllabus for every class, a current list of the materials in its library collection, and the academic standards for each class.",
      "rationale": "Conveys every required posting for participating schools, with the introduction establishing that the summary covers both sets of amended provisions."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "The bill defines \"library collection\" as materials made available to students, including as part of a course. It defines \"materials\" broadly, covering books, periodicals, films, video games, applications, and subscription content in any form.",
      "rationale": "Covers student-accessible and course materials, but the abbreviated materials definition omits newspapers, manuscripts, prints, documents, microfilm, discs, cassettes, and videotapes."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "On staffing, a participating school would have to make sure all its educators hold a valid license to teach in a public school issued by the state board of education.",
      "rationale": "Fully conveys the licensing requirement, presented as applying to participating schools under both sets of provisions."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Section 4 would make the same testing requirements a condition of participating in the program under § 49-6-2606(a)(1).",
      "rationale": "Expressly identifies the amended provision and participation condition, incorporating the previously described annual TCAP or authorized successor testing matched to grade or course subject."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "Section 4 would make the same testing requirements a condition of participating in the program under § 49-6-2606(a)(1).",
      "rationale": "Incorporates the previously identified public-school eleventh-grade examination and makes it a condition of participation under the correct provision."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Section 4 would make the same testing requirements a condition of participating in the program under § 49-6-2606(a)(1).",
      "rationale": "Incorporates the described K–3 screeners, approved alternatives, and three department-established windows as participation conditions, but the incorporated description omits annual administration."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "The act would take effect July 1, 2025.",
      "rationale": "States the exact effective date."
    }
  ]
}
